-- Seed 7 POC threads + briefings
-- Run AFTER migrations 0008 + 0009

-- berkeley-budget
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('Berkeley city budget', 'Berkeley adopted FY 2027-2028 biennial budget on June 23, 2026, closing a $30 million structural deficit through service cuts and layoffs, pending November voter approval of a 0.5% sales tax increase.', 'tracking', 'LOCAL FISCAL', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'berkeley-budget', 'Berkeley city budget', 'LOCAL FISCAL', 'Berkeley adopted FY 2027-2028 biennial budget on June 23, 2026, closing a $30 million structural deficit through service cuts and layoffs, pending November voter approval of a 0.5% sales tax increase.', '2026-06-23', 'Berkeley faces a significant structural deficit estimated at $29-32 million in FY 2027 and $29-33 million in FY 2028, driven by rising labor and pension costs that are growing faster than revenues. The city has historically relied on one-time balancing measures rather than sustainable structural reforms, but the FY 2027-2028 adopted budget represents a shift toward long-term fiscal sustainability through service cuts, position eliminations, and reduced capital investments. The Police Department comprises approximately 32% of General Fund expenditures and has been a focal point in budget discussions. Berkeley''s unfunded pension liability totals $603.5 million, with $1.8 billion in unfunded capital and deferred maintenance needs. The city has placed a 0.5% sales tax measure on the November 2026 ballot, which would generate approximately $9 million annually and is viewed as critical to preventing deeper cuts to police, fire, and recreation services.', '[{"development": "City Council adopted FY 2027-2028 biennial budget on June 23, 2026, implementing structural reforms to address $29-32 million General Fund deficits, including 20 employee layoffs and elimination of 100 vacant positions.", "source_url": "https://berkeleyca.gov/sites/default/files/2026-06/2026-06-23%20Special%20Item%2001%20Adoption%20of%20Fiscal%20Years%202027%20and%202028.pdf"}, {"development": "City placed a 0.5% sales tax measure on November 3, 2026 ballot to generate approximately $9 million annually to support police, fire, and recreation services and prevent deeper cuts.", "source_url": "https://berkeleyca.gov/sites/default/files/2026-06/2026-06-16%20Item%2039%20Placing%20a%20Transactions%20and%20Use.pdf"}, {"development": "City Auditor report (April 2026) identified structural deficit of $32 million in FY 2027 and $33 million in FY 2028, with unfunded pension liability of $603.5 million and $1.8 billion in unfunded capital/deferred maintenance needs.", "source_url": "https://berkeleyca.gov/sites/default/files/2026-04/2026-04-28%20Item%2009%20Berkeley%E2%80%99s%20Financial%20Condition%20%28FY%202016-FY%202025%29.pdf"}, {"development": "Budget Manager Maricar Dupaya announced new strategic approach moving away from one-time balancing measures toward long-term structural adjustments in FY 2027-2028 budget development.", "source_url": "https://berkeleyca.gov/sites/default/files/2026-06/2026-06-16%20Item%2040a%20Proposed%20FY%202027%20and%20FY%202028%20Biennial%20Budget..pdf"}, {"development": "Property Transfer Tax revenue projected to increase from $21 million in FY 2026 to $24.8 million in FY 2027, supporting General Fund despite structural challenges.", "source_url": "https://berkeleyca.gov/sites/default/files/documents/FY-2025-2026-Proposed-Biennial-Budget.pdf"}]'::jsonb, '{"date": "2026-11-03", "body": "Berkeley voters", "what": "Vote on Measure 2 - Transactions and Use (Sales) General Tax Measure to increase sales tax by 0.5% to generate approximately $9 million annually for city services", "source_url": "https://berkeleyca.gov/your-government/elections/ballot-measures"}'::jsonb, '[{"title": "Adopted Budget Fiscal Year 2025-2026", "type": "budget document", "date": "2024-06-25", "url": "https://berkeleyca.gov/sites/default/files/documents/FY-2025-2026-Proposed-Biennial-Budget.pdf", "note": "FY 2025-2026 adopted budget with property transfer tax and revenue forecasts"}, {"title": "Proposed FY 2027 and FY 2028 Biennial Budget and Proposed Biennial Budget Public Hearing #1", "type": "staff report", "date": "2026-05-19", "url": "https://berkeleyca.gov/sites/default/files/2026-05/2026-05-19%20Item%2021%20Proposed%20FY%202027%20and%20FY%202028.pdf", "note": "City Manager presentation of proposed biennial budget with structural deficit analysis"}, {"title": "Proposed FY 2027 and FY 2028 Biennial Budget and Five-Year Capital Improvement Program Public Hearing #2", "type": "staff report", "date": "2026-06-16", "url": "https://berkeleyca.gov/sites/default/files/2026-06/2026-06-16%20Item%2040a%20Proposed%20FY%202027%20and%20FY%202028%20Biennial%20Budget..pdf", "note": "Second public hearing on FY 2027-2028 budget with final adoption recommendation"}, {"title": "Adoption of Fiscal Years 2027 and 2028 Biennial Budget and Capital Improvement Program", "type": "resolution", "date": "2026-06-23", "url": "https://berkeleyca.gov/sites/default/files/2026-06/2026-06-23%20Special%20Item%2001%20Adoption%20of%20Fiscal%20Years%202027%20and%202028.pdf", "note": "Final adopted budget resolution with expenditure allocations and structural reforms"}, {"title": "Placing a Transactions and Use Tax Measure on the November 3, 2026 Ballot", "type": "resolution", "date": "2026-06-16", "url": "https://berkeleyca.gov/sites/default/files/2026-06/2026-06-16%20Item%2039%20Placing%20a%20Transactions%20and%20Use.pdf", "note": "Resolution placing 0.5% sales tax measure on November ballot to address structural deficit"}, {"title": "Berkeley''s Financial Condition (FY 2016-FY 2025): Structural Deficit Poses Risk to Financial Sustainability", "type": "staff report", "date": "2026-04-28", "url": "https://berkeleyca.gov/sites/default/files/2026-04/2026-04-28%20Item%2009%20Berkeley%E2%80%99s%20Financial%20Condition%20%28FY%202016-FY%202025%29.pdf", "note": "City Auditor report on long-term fiscal challenges and structural deficit risks"}, {"title": "Proposed FY 2027 - FY 2031 Capital Improvement Program", "type": "staff report", "date": "2026-05-28", "url": "https://berkeleyca.gov/sites/default/files/legislative-body-meeting-attachments/Item%2002%205.28.26%20B%26FPC%20Item2%20FY%2027%20%E2%80%93%20FY%2031%20Proposed%20CIP.pdf", "note": "Proposed five-year capital improvement program addressing deferred maintenance"}, {"title": "FY 2026 Proposed Budget Update Adoption", "type": "resolution", "date": "2025-06-24", "url": "https://berkeleyca.gov/sites/default/files/documents/2025-06-24%20Item%2024%20FY%202026%20Proposed%20Budget%20Update%20Adoption.pdf", "note": "Mid-biennial budget update for FY 2026 addressing deficit and one-time measures"}, {"title": "City Council Regular Meeting eAgenda June 23, 2026", "type": "council agenda", "date": "2026-06-23", "url": "https://berkeleyca.gov/city-council-special-meeting-eagenda-june-23-2026", "note": "Special meeting agenda for final budget and appropriations ordinance adoption"}, {"title": "Ballot Measures", "type": "ordinance", "date": "2026-06-16", "url": "https://berkeleyca.gov/your-government/elections/ballot-measures", "note": "Official city webpage listing all measures on November 3, 2026 ballot including sales tax measure"}]'::jsonb, '[{"title": "Berkeley approves budget with service cuts, layoffs", "outlet": "Berkeleyside", "date": "2026-06-24", "url": "https://www.berkeleyside.org/2026/06/24/berkeley-budget-sales-tax-firefighters"}, {"title": "Berkeley budget deficit could spur layoffs, cuts and a tax increase", "outlet": "Berkeleyside", "date": "2026-04-15", "url": "https://www.berkeleyside.org/2026/04/15/berkeley-budget-deficit-sales-tax-layoffs"}, {"title": "Berkeley hopes new budget strategy will curb rising costs", "outlet": "Berkeley Scanner", "date": "2026-05-19", "url": "https://www.berkeleyscanner.com/2026/05/19/community/berkeley-new-budget-strategy-rising-costs-deficit"}, {"title": "City Council approves $829M budget amid structural deficit", "outlet": "Daily Californian", "date": "2026-06-24", "url": "https://www.dailycal.org/news/city/city-council-approves-829m-budget-amid-structural-deficit/article_def5f03d-63cf-47f3-9130-193fc42068a1.html"}, {"title": "Berkeley Closes $30M Budget Gap, but November Tax Vote Looms as Fiscal Lifeline", "outlet": "East Bay Insiders", "date": "2026-06-24", "url": "https://eastbayinsiders.substack.com/p/berkeley-closes-30m-budget-gap-but"}]'::jsonb, '[{"title": "Research Update: Berkeley, CA Series 2026 Infrastructure", "author_org": "S&P Global Ratings", "url": "https://www.spglobal.com/ratings/en/regulatory/article/-/view/type/HTML/id/3593230"}]'::jsonb, '["Detailed impact analysis of specific service cuts and program eliminations across city departments beyond police and fire", "Implementation timeline and transition plans for the 20 employee layoffs and 100 position eliminations", "Revenue projections for FY 2027-2028 from sources beyond property transfer tax and sales tax measure", "Analysis of how structural reforms will impact long-term pension and OPEB liability trends", "Contingency planning if the November 2026 sales tax measure fails to gain voter approval"]'::jsonb, 21, 15, now());
END $$;

-- ca-cap-trade
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('California Cap-and-Invest Program', 'CARB adopted comprehensive amendments to California''s Cap-and-Invest Program on May 29, 2026, tightening allowance budgets through 2030 and establishing new post-2030 trajectories to align with state climate targets.', 'tracking', 'PROGRAM/POLICY', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'ca-cap-trade', 'California Cap-and-Invest Program', 'PROGRAM/POLICY', 'CARB adopted comprehensive amendments to California''s Cap-and-Invest Program on May 29, 2026, tightening allowance budgets through 2030 and establishing new post-2030 trajectories to align with state climate targets.', '2026-06-10', 'California''s Cap-and-Invest Program (formerly Cap-and-Trade) is a cornerstone of the state''s climate strategy, establishing a declining limit on greenhouse gas emissions from major sources and creating economic incentives for clean energy investment. The program was extended through 2045 by the Legislature in 2025 through AB 1207 and SB 840, mandating CARB to align allowance budgets with the state''s 40% emissions reduction target by 2030 and 85% reduction by 2045. CARB released proposed amendments in January 2026 and, following public comment periods and stakeholder engagement, the Board voted May 28-29, 2026 to adopt the amendments with revisions. The updated regulation is scheduled to take effect September 1, 2026, and includes tighter allowance caps, new industry incentive mechanisms, affordability measures, and revised offset protocols.', '[{"development": "CARB Board voted May 28-29, 2026 to adopt Cap-and-Invest amendments without further modifications, maintaining September 1, 2026 implementation timeline", "source_url": "https://ww2.arb.ca.gov/news/carb-adopts-updates-californias-cap-and-invest-program-support-affordability-and-align-climate"}, {"development": "Amendments remove approximately 118 million allowances from 2027-2030 annual budgets to align with 40% GHG reduction target by 2030", "source_url": "https://ww2.arb.ca.gov/sites/default/files/barcu/board/books/2026/052826/26-7prores.pdf"}, {"development": "New industry incentive mechanism (Market Driven Investment/MDI) creates $4 billion fund for decarbonization projects but subject to Board review before allowance issuance", "source_url": "https://www.kqed.org/news/12085401/amid-opposition-california-regulators-approve-major-changes-to-cap-and-trade-program"}, {"development": "Offset credits now placed ''under the cap''—when entities use offsets for compliance, equivalent allowances are retired from following year''s budget", "source_url": "https://icapcarbonaction.com/en/news/california-air-resources-board-adopts-regulatory-updates-cap-and-invest-program"}, {"development": "Post-2030 allowance budgets established with new trajectory averaging 7% annual decline from 2031-2045 to meet 85% emissions reduction goal", "source_url": "https://icapcarbonaction.com/en/news/california-air-resources-board-adopts-regulatory-updates-cap-and-invest-program"}, {"development": "Cap Adjustment Factors for industrial activities maintained through 2031, with approximately $800 million in additional compliance support through upward adjustments", "source_url": "https://icapcarbonaction.com/en/news/california-air-resources-board-adopts-regulatory-updates-cap-and-invest-program"}, {"development": "CARB page updated June 10, 2026 noting post-May 28 Board adoption and confirming regulatory amendments posted May 26 and April 14, 2026", "source_url": "https://ww2.arb.ca.gov/rulemaking/2026/cap-and-invest2026"}]'::jsonb, '{"date": "Summer 2026", "body": "California Air Resources Board", "what": "Workshop on updating compliance offset protocols as required under AB 1207 and SB 840", "source_url": "https://icapcarbonaction.com/en/news/california-air-resources-board-adopts-regulatory-updates-cap-and-invest-program"}'::jsonb, '[{"title": "Proposed Amendments to the California Cap on Greenhouse Gas Emissions and Market-Based Compliance Mechanisms Regulation Resolution 26-7", "type": "Board Resolution", "date": "2026-05-28", "url": "https://ww2.arb.ca.gov/sites/default/files/barcu/board/books/2026/052826/26-7prores.pdf", "note": "Official CARB resolution adopting Cap-and-Invest amendments with removal of 118M+ allowances through 2030 and 900M+ post-2030"}, {"title": "Staff Report: Initial Statement of Reasons", "type": "Regulatory Proposal", "date": "2026-01-20", "url": "https://ww2.arb.ca.gov/sites/default/files/cap-and-trade/regulation/nc-Staff%20Report%20-%20Initial%20Statement%20of%20Reasons%20(ISOR).pdf", "note": "CARB staff proposal released January 20, 2026 for May 28 Board consideration"}, {"title": "Response to Comments Proposed Amendments to Cap-and-Invest", "type": "Comment Response Document", "date": "2026-05-26", "url": "https://ww2.arb.ca.gov/sites/default/files/barcu/regact/2026/cap_invest/ceqa_rtc.pdf", "note": "CARB responses to public comments submitted during rulemaking, released May 26, 2026"}, {"title": "Notice of Public Hearing to Consider Proposed Amendments", "type": "Public Notice", "date": "2026-05-28", "url": "https://ww2.arb.ca.gov/sites/default/files/barcu/regact/2026/cap_invest/nc_notice.pdf", "note": "CARB public hearing notice for May 28-29, 2026 Board meeting with detailed background on 2025 legislative direction"}, {"title": "Appendix C - SRIA, DOF Comments, CARB Responses", "type": "Regulatory Impact Analysis", "date": "2026-01-20", "url": "https://ww2.arb.ca.gov/sites/default/files/barcu/regact/2026/cap_invest/nc_app%20c.pdf", "note": "Health benefits analysis showing $200B in 2045 benefits and criteria pollutant reductions through 2046"}, {"title": "California Cap on Greenhouse Gas Emissions and Market-Based Compliance Mechanisms Regulation", "type": "Rulemaking Page", "date": "2026-06-10", "url": "https://ww2.arb.ca.gov/rulemaking/2026/cap-and-invest2026", "note": "CARB rulemaking page last reviewed June 10, 2026 with links to all regulatory documents and amendments"}, {"title": "Cap-and-Invest Regulation", "type": "Regulatory Framework", "date": "2026-06-10", "url": "https://ww2.arb.ca.gov/our-work/programs/cap-and-trade-program/cap-and-invest-regulation", "note": "Current and historical Cap-and-Invest regulations including 2026 amendments framework"}, {"title": "CARB Proposes Updates to Cap-and-Invest Program", "type": "Program Announcement", "date": "2026-01-13", "url": "https://ww2.arb.ca.gov/resources/documents/carb-proposes-updates-cap-and-invest-program", "note": "CARB announcement of January 13, 2026 draft updates following 2025 legislative extension through 2045"}]'::jsonb, '[{"title": "Amid Opposition, California Regulators Approve Major Changes To Cap-And-Trade Program", "outlet": "KQED", "date": "2026-05-29", "url": "https://www.kqed.org/news/12085401/amid-opposition-california-regulators-approve-major-changes-to-cap-and-trade-program"}, {"title": "Policy Perspective by Jon Costantino: The May 2026 Cap-and-Invest Board Meeting. What did we learn?", "outlet": "California Renewable Transportation Alliance", "date": "2026-05-29", "url": "https://ca-rta.org/policy-perspective-by-jon-costantino-the-may-2026-cap-and-invest-board-meeting-what-did-we-learn"}, {"title": "California ARB Presents A New 2030 Allowance Budget", "outlet": "cCarbon", "date": "2026-07-10", "url": "https://www.ccarbon.info/article/california-arb-presents-a-new-2030-allowance-budget-scenario-and-a-roll-out-starting-2026"}, {"title": "CARB Proposes Amendments to California''s Cap-and-Trade Rules", "outlet": "California Energy Journal", "date": "2026-01-23", "url": "https://www.californiaenergytransition.com/p/carb-proposes-amendments-to-californias"}, {"title": "Why are California Carbon Prices so Low?", "outlet": "Energy Institute Blog", "date": "2026-02-09", "url": "https://energyathaas.wordpress.com/2026/02/09/why-are-california-carbon-prices-so-low"}, {"title": "California''s Cap-and-Trade Is Extended and Becomes ''Cap-and-Invest'' in Package of New Energy Laws", "outlet": "Greenberg Traurig LLP", "date": "2025-10-13", "url": "https://www.gtlaw.com/en/insights/2025/10/californias-cap-and-trade-is-extended-and-becomes-cap-and-invest-in-package-of-new-energy-laws"}]'::jsonb, '[{"title": "California Air Resources Board adopts regulatory updates to the Cap-and-Invest Program", "author_org": "International Carbon Action Partnership", "url": "https://icapcarbonaction.com/en/news/california-air-resources-board-adopts-regulatory-updates-cap-and-invest-program"}, {"title": "California extends cap-and-trade to 2045, renames program ''Cap-and-Invest''", "author_org": "International Carbon Action Partnership", "url": "https://icapcarbonaction.com/en/news/california-extends-cap-and-trade-2045-renames-program-cap-and-invest"}, {"title": "USA - California Cap-and-Invest Program", "author_org": "International Carbon Action Partnership", "url": "https://icapcarbonaction.com/en/ets/usa-california-cap-and-invest-program"}, {"title": "Cap-and-Invest: November 2025 Auction Update and 2026-27 Budget Context", "author_org": "California Legislative Analyst''s Office", "url": "https://www.lao.ca.gov/Publications/Report/5096"}, {"title": "Joint Legislative Committee on Climate Change Policies Hearing Background", "author_org": "California Legislature", "url": "https://climatechangepolicies.legislature.ca.gov/system/files/2026-02/jlcccp-hearing-background-2_23_26.pdf"}, {"title": "California Climate Disclosure Laws: What CARB''s February 2026 Approval Means for Your Compliance Timeline", "author_org": "CO2 AI", "url": "https://co2ai.com/insights/california-climate-disclosure-laws-what-carbs-february-2026-approval-means-for-your-compliance-timeline"}, {"title": "California climate laws - KPMG International", "author_org": "KPMG International", "url": "https://kpmg.com/us/en/frv/reference-library/2026/california-climate-laws.html"}, {"title": "Reforming California''s Cap and Trade Program Policy Brief", "author_org": "The Climate Center", "url": "https://theclimatecenter.org/wp-content/uploads/2023/11/Reforming-Californias-Cap-and-Trade-Program-Policy-Brief-The-Climate-Center.pdf"}]'::jsonb, '["Details on August 2026 Joint Auction #48 outcomes (scheduled but not yet occurred as of as_of date)", "Specific text of September 1, 2026 effective regulation not yet available", "Details on Market Driven Investment (MDI) fund allocation methodology and decarbonization project review criteria", "Complete list of changes to compliance offset protocols beyond the 6% allowance limit", "CARB''s report to Legislature on offsets evaluation (due December 31, 2026) not yet completed", "Final rulemaking outcomes from Quebec and Washington State linkage exploration", "Specific impact analysis on electricity rates and natural gas prices post-implementation", "Detailed allowance allocation percentages for 2027-2030 by sector (utility, industrial, transportation)"]'::jsonb, 29, 13, now());
END $$;

-- ggf-redesign
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('Golden Gate Fields redesign (Albany/Berkeley)', 'California State Legislature approved $125M in Proposition 4 Climate Bond funding (June 15, 2026 budget deadline met); Trust for Public Land option extended through end of 2026 to secure remaining $30M in funding; spring 2027 acquisition closing and 2027-2029 community planning process anticipated.', 'tracking', 'PROJECT/LAND USE', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'ggf-redesign', 'Golden Gate Fields redesign (Albany/Berkeley)', 'PROJECT/LAND USE', 'California State Legislature approved $125M in Proposition 4 Climate Bond funding (June 15, 2026 budget deadline met); Trust for Public Land option extended through end of 2026 to secure remaining $30M in funding; spring 2027 acquisition closing and 2027-2029 community planning process anticipated.', '2026-07-08', 'Golden Gate Fields was a thoroughbred horse racing facility in Albany and Berkeley that closed in June 2024 after 80+ years of operation under the Stronach Group''s ownership since 1999. In March 2026, the Trust for Public Land secured an option agreement to purchase the 162-acre waterfront property for $175M with the goal of converting it into a regional public park. Governor Newsom''s May 2026 budget proposal allocated $125M from Proposition 4 (Climate Bond), which was approved by the state legislature on the June 15, 2026 deadline, covering 71% of the purchase price. EBRPD committed $20M from Measure WW, leaving approximately $30M to be raised through private philanthropy. The acquisition is expected to close in spring 2027, followed by a community planning process in 2027-2029 and phased park development beginning beyond 2029.', '[{"development": "California State Legislature approved Governor Newsom''s revised budget proposal allocating $125M from Proposition 4 (Climate Bond) for the acquisition by June 15, 2026 state budget deadline, meeting nearly 71% of the $175M purchase price", "source_url": "https://sbud.senate.ca.gov/system/files/2026-05/sub-2-resources-close-out-agenda-may-28-resources-part-a-05.27_.pdf"}, {"development": "Berkeley Parks, Recreation, and Waterfront Commission created a Golden Gate Fields subcommittee (April 8, 2026) comprising Commissioners Nash, Muszynski, and Stewart to track the acquisition and community planning process", "source_url": "https://berkeleyca.gov/sites/default/files/legislative-body-meeting-minutes/PRW%20Minutes%20-%20Draft%20-%202026-05-13.pdf"}, {"development": "Trust for Public Land and East Bay Regional Park District issued joint statements in May 2026 expressing commitment to the acquisition with $125M state funding secured and EBRPD''s $20M Measure WW commitment", "source_url": "https://www.tpl.org/media-room/trust-public-land-and-east-bay-regional-park-district-issue-joint-statements-following-125-million-state-investment-to-help-protect-golden-gate-fields-for-future-waterfront-park"}, {"development": "Berkeley Commission received status update (July 8, 2026) confirming $175M purchase price includes removal of existing above-ground structures; acquisition structured as TPL purchase followed by transfer to EBRPD as long-term owner and steward", "source_url": "https://berkeleyca.gov/sites/default/files/legislative-body-meeting-attachments/GGF_Status_Update_2026-07-08_rev_2.pdf"}, {"development": "Senator Jesse Arreguín applauded Governor Newsom''s $125M investment (May 2026), noting the acquisition culminates a multi-year stakeholder process that began during his tenure as Berkeley Mayor", "source_url": "https://sd07.senate.ca.gov/news/senator-arreguin-applauds-governor-newsoms-support-transforming-golden-gate-fields-new-public"}, {"development": "City of Albany expressed concerns about loss of property tax revenue if Trust for Public Land (a tax-exempt nonprofit) acquired the property, noting dependency on Golden Gate Fields revenues for city services", "source_url": "https://www.dailycal.org/news/city/newsom-budget-proposal-allocates-125m-to-convert-golden-gate-fields-into-park/article_df84e4a0-ab1a-4768-b467-a168086906ba.html"}, {"development": "Conservation coalition groups (TOGETHER Bay Area) raised concerns that $125M Proposition 4 earmark for Golden Gate Fields diverts funds from other $1.26B in conservation projects on their combined priority list", "source_url": "https://www.berkeleyside.org/2026/06/05/golden-gate-fields-gavin-newsom-berkeley-prop-4"}]'::jsonb, '{"date": "2026-12-31", "body": "Trust for Public Land", "what": "Final deadline to secure full $175M purchase price funding and complete acquisition transaction; if deadline not met, option agreement expires and deal collapses", "source_url": "https://www.tpl.org/our-work/golden-gate-fields"}'::jsonb, '[{"title": "Golden Gate Fields Acquisition: Status Update (Berkeley Parks, Recreation, and Waterfront Commission)", "type": "Commission Information Communication", "date": "2026-07-08", "url": "https://berkeleyca.gov/sites/default/files/legislative-body-meeting-attachments/GGF_Status_Update_2026-07-08_rev_2.pdf", "note": "Latest official status from Berkeley commission on acquisition structure, funding status, and next steps"}, {"title": "Senate Budget and Fiscal Review Committee: Subcommittee No. 2 May 28, 2026 - Issue 3: Climate Bond (Proposition 4) 2026-27 Expenditure Plan Adjustments", "type": "State Budget Document", "date": "2026-05-28", "url": "https://sbud.senate.ca.gov/system/files/2026-05/sub-2-resources-close-out-agenda-may-28-resources-part-a-05.27_.pdf", "note": "State legislative record of $148.2M Climate Bond appropriation for Golden Gate Fields acquisition from multiple bond sections"}, {"title": "City of Albany - Golden Gate Fields Transition", "type": "City webpage", "date": "", "url": "https://www.albanyca.org/Residents/Parks-Open-Space/Waterfront/Golden-Gate-Fields-Transition", "note": "Albany''s official transition documentation and position on the acquisition"}, {"title": "East Bay Regional Park District - Future Golden Gate Fields Park", "type": "Agency project page", "date": "", "url": "https://www.ebparks.org/projects/future-planning/future-golden-gate-fields-park", "note": "EBRPD comprehensive project information including timeline, FAQs, and acquisition structure"}, {"title": "Trust for Public Land - Golden Gate Fields Project Page", "type": "Nonprofit project page", "date": "", "url": "https://www.tpl.org/our-work/golden-gate-fields", "note": "TPL official project page with acquisition goals and partnership details"}, {"title": "Parks, Recreation, and Waterfront Commission Minutes - May 13, 2026", "type": "Commission minutes", "date": "2026-05-13", "url": "https://berkeleyca.gov/sites/default/files/legislative-body-meeting-minutes/PRW%20Minutes%20-%20Draft%20-%202026-05-13.pdf", "note": "Record of Berkeley Commission creating Golden Gate Fields subcommittee"}]'::jsonb, '[{"title": "Critics question Newsom''s $125M earmark for Golden Gate Fields", "outlet": "Berkeleyside", "date": "2026-06-05", "url": "https://www.berkeleyside.org/2026/06/05/golden-gate-fields-gavin-newsom-berkeley-prop-4"}, {"title": "Newsom Wants Prop 4 Funds for Golden Gate Fields. Some Local Conservationists Have Other Priorities.", "outlet": "Bay Nature", "date": "2026-06-04", "url": "https://baynature.org/2026/06/04/conservation/parks/newsom-wants-prop-4-funds-for-golden-gate-fields-some-local-conservationists-have-other-priorities"}, {"title": "Newsom''s budget would help turn Golden Gate Fields horse track into park", "outlet": "San Francisco Chronicle", "date": "2026-05", "url": "https://www.sfchronicle.com/bayarea/article/golden-gate-fields-newsom-budget-22257829.php"}, {"title": "Newsom budget proposal allocates $125M to convert Golden Gate Fields into park", "outlet": "Daily Californian", "date": "2026-05", "url": "https://www.dailycal.org/news/city/newsom-budget-proposal-allocates-125m-to-convert-golden-gate-fields-into-park/article_df84e4a0-ab1a-4768-b467-a168086906ba.html"}, {"title": "Senator Arreguín Applauds Governor Newsom''s Support for Transforming Golden Gate Fields into a New Public Waterfront Park", "outlet": "California State Senate District 7", "date": "2026-05-14", "url": "https://sd07.senate.ca.gov/news/senator-arreguin-applauds-governor-newsoms-support-transforming-golden-gate-fields-new-public"}, {"title": "Trust for Public Land and East Bay Regional Park District Issue Joint Statements Following $125 Million State Investment", "outlet": "Trust for Public Land", "date": "2026-05-14", "url": "https://www.tpl.org/media-room/trust-public-land-and-east-bay-regional-park-district-issue-joint-statements-following-125-million-state-investment-to-help-protect-golden-gate-fields-for-future-waterfront-park"}, {"title": "Trust for Public Land and East Bay Regional Park District Issue Joint Statements Following $125 Million State Investment to Help Protect Golden Gate Fields for Future Waterfront Park", "outlet": "East Bay Regional Park District", "date": "2026-05-14", "url": "https://www.ebparks.org/about-us/whats-new/news/trust-public-land-and-east-bay-regional-park-district-issue-joint"}, {"title": "Golden Gate Fields park deal: All the latest details", "outlet": "Berkeley Scanner", "date": "2026-05-15", "url": "https://www.berkeleyscanner.com/2026/05/15/community/golden-gate-fields-park-deal-latest-details"}, {"title": "Plan to turn Golden Gate Fields into waterfront park could get $125M from state", "outlet": "Berkeleyside", "date": "2026-05-14", "url": "https://www.berkeleyside.org/2026/05/14/golden-gate-fields-park-newsom-may-revise-berkeley"}, {"title": "Environmental group signs deal to buy Golden Gate Fields horse track with plans to create huge new East Bay waterfront park", "outlet": "Mercury News", "date": "2026-03-31", "url": "https://www.mercurynews.com/2026/03/31/environmental-group-signs-deal-to-buy-golden-gate-fields-horse-track-with-plans-to-create-huge-new-east-bay-waterfront-park"}, {"title": "Trust for Public Land Secures Option on Former Golden Gate Fields Site", "outlet": "Trust for Public Land", "date": "2026-03-31", "url": "https://www.tpl.org/media-room/trust-public-land-secures-option-on-former-golden-gate-fields-site-launching-effort-in-partnership-with-east-bay-regional-park-district-to-transform-161-acre-waterfront-into-future-east"}, {"title": "Trust for Public Land Secures Option on Former Golden Gate Fields Site", "outlet": "East Bay Regional Park District", "date": "2026-03", "url": "https://www.ebparks.org/about-us/whats-new/news/trust-public-land-secures-option-former-golden-gate-fields-site-launching"}, {"title": "Golden Gate Fields could soon turn into a public park", "outlet": "Berkeleyside", "date": "2026-03-31", "url": "https://www.berkeleyside.org/2026/03/31/golden-gate-fields-sold-park-albany-berkeley"}, {"title": "East Bay Racetrack Golden Gate Fields Could Soon Be a New Public Waterfront Park", "outlet": "KQED", "date": "2026-03", "url": "https://www.kqed.org/news/12078396/east-bay-racetrack-golden-gate-fields-could-soon-be-a-new-public-waterfront-park"}]'::jsonb, '[{"title": "Advanced Urban Design & Planning Studio: Golden Gate Fields", "author_org": "UC Berkeley College of Environmental Design", "url": "https://ced.berkeley.edu/work/studio-urban-design-environment-ggf"}]'::jsonb, '["Current status of TPL''s $30M funding gap closure efforts through private philanthropy since May 2026", "Details on Albany''s formal position regarding property tax revenue loss and any negotiations with TPL", "Specific community engagement plans for the 2027-2029 planning process announced after July 2026", "Complete environmental remediation scope and timeline for the site beyond demolition", "Detailed master plan or design concept for future park amenities and habitat restoration", "Outcome and details of Berkeley Commission''s July 2026 subcommittee work on the project", "Resolution of conservation coalition concerns about Proposition 4 funding allocation", "Details on TPL''s philanthropic fundraising strategy and progress toward $30M gap since June 2026", "Specific response from Cities of Albany and Berkeley to June/July 2026 status updates"]'::jsonb, 28, 11, now());
END $$;

-- la-fire-insurance
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('LA fire insurance coverage & FAIR Plan', 'California FAIR Plan faces record $6+ billion exposure from 2025 LA wildfires amid regulatory enforcement, rate hikes, and legislative reform efforts including proposed AB 1680.', 'tracking', 'REGULATORY/MARKET', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'la-fire-insurance', 'LA fire insurance coverage & FAIR Plan', 'REGULATORY/MARKET', 'California FAIR Plan faces record $6+ billion exposure from 2025 LA wildfires amid regulatory enforcement, rate hikes, and legislative reform efforts including proposed AB 1680.', '2026-06-30', 'California''s FAIR Plan (Fair Access to Insurance Requirements) is the state''s insurer of last resort for homeowners unable to obtain coverage in the private market. Entered 2025 with ~$600 billion in exposure and 550,000+ policies, growing ~40% annually as major insurers like State Farm and Allstate retreated from or halted sales in California. The January 2025 Palisades and Eaton fires created an estimated $6+ billion exposure—the FAIR Plan''s largest loss in history—triggering a $1 billion assessment on member insurers, half of which may be passed to customers via premium surcharges. Policy non-renewals affected over 2.8 million homeowners between 2020-2025 in fire-prone areas. Regulatory scrutiny intensified dramatically in 2025-2026, with Commissioner Lara filing legal action against FAIR Plan for 418 consumer protection violations including systematic denial of smoke damage claims, while the Legislature advanced AB 1680 (Make It FAIR Act) requiring comprehensive coverage expansion and governance reforms.', '[{"development": "Commissioner Lara defeats Consumer Watchdog lawsuit challenging FAIR Plan assessment pass-through authority; median homeowner fee upheld at $28/year", "source_url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2026/release022-2026.cfm"}, {"development": "Make It FAIR Act (AB 1680) announced, requiring FAIR Plan to offer comprehensive homeowners coverage, hire staff, open meetings, and implement climate assessments; administrative law judge hearings scheduled for later 2026", "source_url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2026/release005-2026.cfm"}, {"development": "Assembly Insurance Committee Oversight Hearing (January 28, 2026) found FAIR Plan non-compliant in more than half of 32 areas examined", "source_url": "https://ains.assembly.ca.gov/system/files/2026-01/1.28.26-fair-plan-background-final.pdf"}, {"development": "Mercury Insurance and CSAA received first SIS rate approvals at 6.9%; Mercury committed to 38,000+ new policies; CSAA preparing to depopulate FAIR Plan", "source_url": "https://www.latentinsure.com/blog/california-homeowners-insurance-news"}, {"development": "CDI reported FAIR Plan filed legal action against 418 violations of consumer protection laws, with pattern of denying smoke damage claims; over 220 smoke-related complaints since January 2025", "source_url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2025/release054-2025.cfm"}, {"development": "FAIR Plan sought 36% average rate hike in October 2025, with some policyholders facing 40-55% increases or up to 300%+ in extreme cases", "source_url": "https://stateline.org/2025/10/24/californias-last-resort-property-insurer-seeks-rate-hike-ringing-national-alarm-bells/"}, {"development": "New commercial FAIR Plan policy effective July 26, 2025 offering up to $100M aggregate per location, expiring 2028 as private market recovers", "source_url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2025/release055-2025.cfm"}, {"development": "Stipulation and Order No. 2026-1 requires Commissioner and FAIR Plan to work together on additional financing sources with quarterly reporting beginning July 1, 2025", "source_url": "https://www.insurance.ca.gov/0250-insurers/0500-legal-info/0700-commissioners-orders/upload/FAIR-Plan-Stipulation-and-Order-No-2026-1.pdf"}, {"development": "AB 226 (FAIR Plan Stability Act) signed by Governor, allowing CA Infrastructure and Economic Development Bank to issue bonds on behalf of FAIR Plan, effective by April 1, 2026", "source_url": "https://www.heffins.com/what-newsoms-new-laws-mean-for-the-california-fair-plan/"}, {"development": "State Farm reversed non-renewal of 70,000+ policies but requires policyholders to obtain fire coverage through FAIR Plan", "source_url": "https://uphelp.org/state-farm-reverses-california-policy-non-renewals-with-a-catch/?print=print"}]'::jsonb, '{"date": "2026-Q3/Q4", "body": "California Administrative Law Judge", "what": "Hearings on CDI legal action against FAIR Plan for 418 consumer protection law violations and smoke damage claim denials", "source_url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2025/release054-2025.cfm"}'::jsonb, '[{"title": "Commissioner''s Order No. 2025-1: Approved FAIR Plan $1 billion assessment from member companies", "type": "order", "date": "2025-02", "url": "https://www.insurance.ca.gov/0250-insurers/0500-legal-info/0700-commissioners-orders/upload/Order-No-2025-1-Approving-the-California-FAIR-Plan-Association-s-Request-to-Issue-Assessment.pdf", "note": "Authorized $1 billion assessment to cover losses from January 2025 wildfires"}, {"title": "Stipulation and Order No. 2026-1", "type": "order", "date": "2026", "url": "https://www.insurance.ca.gov/0250-insurers/0500-legal-info/0700-commissioners-orders/upload/FAIR-Plan-Stipulation-and-Order-No-2026-1.pdf", "note": "Requires Commissioner and FAIR Plan coordination on financing; quarterly reporting began July 1, 2025"}, {"title": "CDI Bulletin 2025-1: Mandatory non-renewal moratorium", "type": "bulletin", "date": "2025", "url": "https://www.insurance.ca.gov/0250-insurers/0300-insurers/0200-bulletins/bulletin-notices-commiss-opinion/upload/Bulletin-2025-1-One-Year-Moratorium-Updated-ZIP-Codes-Amended-17-January-2025.pdf", "note": "One-year moratorium on non-renewals/cancellations in ZIP codes near Palisades, Eaton, Hurst, Lidia, Sunset, Woodley fire perimeters; protects ~1 million LA County residents"}, {"title": "New Laws Effective January 1, 2026", "type": "law", "date": "2026-01-01", "url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2025/release079-2025.cfm", "note": "Wildfire safety grants, expanded discounts, faster claim payouts, business non-renewal protections, FAIR Plan financial stability measures"}, {"title": "Make It FAIR Act (AB 1680)", "type": "law", "date": "2026-02-02", "url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2026/release005-2026.cfm", "note": "Proposed legislation requiring FAIR Plan comprehensive coverage, staffing increases, open meetings, climate risk assessments, strategic planning; administrative law judge hearings scheduled 2026"}, {"title": "AB 226 (FAIR Plan Stability Act)", "type": "law", "date": "2026-04-01", "url": "https://www.heffins.com/what-newsoms-new-laws-mean-for-the-california-fair-plan/", "note": "Allows CA Infrastructure and Economic Development Bank to issue bonds for FAIR Plan; effective by April 1, 2026"}]'::jsonb, '[{"title": "Commissioner Lara takes legal action against FAIR Plan for denying smoke damage claims", "outlet": "California Department of Insurance", "date": "2025-07-31", "url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2025/release054-2025.cfm"}, {"title": "California''s Last-Resort Property Insurer Seeks Rate Hike, Ringing National Alarm Bells", "outlet": "Stateline", "date": "2025-10-24", "url": "https://stateline.org/2025/10/24/californias-last-resort-property-insurer-seeks-rate-hike-ringing-national-alarm-bells/"}, {"title": "FAIR Plan enters 2025 with ~$600 billion exposure and 550,000+ policies; grows to 600,000+ policies and ~$650 billion exposure", "outlet": "Insurance Business Magazine", "date": "2025", "url": "https://www.insurancebusinessmag.com/us/news/catastrophe/californias-fair-plan-carries-growing-load-as-insurers-retreat-beyond-wildfire-zones-568596.aspx"}, {"title": "FAIR Plan faces estimated $6+ billion in exposure from Palisades/Eaton fires", "outlet": "Apex Adjusting Group", "date": "2025", "url": "https://www.apexadjustinggroup.com/blog/fair-plan-claims-california-wildfires-2025"}, {"title": "State Farm reverses non-renewal of 70,000+ policies but requires fire coverage through FAIR Plan", "outlet": "UPHELP", "date": "2025-2026", "url": "https://uphelp.org/state-farm-reverses-california-policy-non-renewals-with-a-catch/?print=print"}, {"title": "California says State Farm violated law in handling claims after 2025 LA wildfires", "outlet": "CNN", "date": "2026-05-04", "url": "https://www.cnn.com/2026/05/04/us/la-fires-2025-state-farm-home-insurance"}, {"title": "Commissioner Lara defeats Consumer Watchdog lawsuit challenging insurance market reforms", "outlet": "California Department of Insurance", "date": "2026-06-30", "url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2026/release022-2026.cfm"}, {"title": "Make It FAIR Act (AB 1680) announced with administrative law judge hearings scheduled for 2026", "outlet": "California Department of Insurance", "date": "2026-02-02", "url": "https://www.insurance.ca.gov/0400-news/0100-press-releases/2026/release005-2026.cfm"}]'::jsonb, '[{"title": "Milliman analysis of California homeowners insurance and LA wildfires", "author_org": "Milliman", "url": "https://www.milliman.com/en/insight/california-homeowners-insurance-los-angeles-wildfires"}, {"title": "California''s Wildfire Insurance Crisis", "author_org": "Taxpayers for Common Sense", "url": "https://www.taxpayer.net/wp-content/uploads/2025/11/tcs-CA-insurance-2025.pdf"}, {"title": "CDI Fact Sheet on Residential Insurance Policies and FAIR Plan", "author_org": "California Department of Insurance", "url": "https://www.insurance.ca.gov/01-consumers/200-wrr/upload/CDI-Fact-Sheet-Summary-on-Residential-Insurance-Policies-and-the-FAIR-Plan.pdf"}, {"title": "Assembly Insurance Committee Oversight Hearing on California FAIR Plan", "author_org": "California Assembly", "url": "https://ains.assembly.ca.gov/system/files/2026-01/1.28.26-fair-plan-background-final.pdf"}, {"title": "California Insurance News and Analysis", "author_org": "LatentInsure", "url": "https://www.latentinsure.com/blog/california-homeowners-insurance-news"}, {"title": "What Newsom''s New Laws Mean for the California FAIR Plan", "author_org": "HeffinsInsurance", "url": "https://www.heffins.com/what-newsoms-new-laws-mean-for-the-california-fair-plan/"}]'::jsonb, '["Specific timeline or decision date for AB 1680 administrative law judge hearings beyond ''later in 2026''", "Details on current FAIR Plan financial reserve status post-assessment", "Comprehensive breakdown of smoke damage claim denials by fire event beyond aggregate numbers", "Status of 2026 Insurance Commissioner election outcomes and candidate proposals", "Full text and approval status of Sustainable Insurance Strategy (SIS) requirements beyond Mercury/CSAA approvals", "Specific details on State Farm claims violations findings from May 2026 CDI action", "Public comment or outcome from Senate Standing Committee on Insurance hearing (June 24, 2026)", "Details on CDI''s recovery of $74 million for wildfire survivors mentioned in press release", "Projected timeline for private market recovery and FAIR Plan exit strategies", "Complete list of catastrophe modeling vendors evaluated by CDI beyond Verisk, Karen Clark, Moody''s"]'::jsonb, 30, 17, now());
END $$;

-- oakland-charter
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('Oakland charter reform', 'Oakland''s charter reform measure establishing a strong mayor system was advanced to the November 2026 ballot after Mayor Barbara Lee cast a tie-breaking vote on June 16, 2026.', 'tracking', 'GOVERNANCE/BALLOT', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'oakland-charter', 'Oakland charter reform', 'GOVERNANCE/BALLOT', 'Oakland''s charter reform measure establishing a strong mayor system was advanced to the November 2026 ballot after Mayor Barbara Lee cast a tie-breaking vote on June 16, 2026.', '2026-06-18', 'Oakland is pursuing significant charter reform that would establish a strong mayor system, fundamentally changing the city''s governance structure for the first time in decades. The current system has the mayor as a non-voting administrator overseeing day-to-day operations, while the city council handles legislation and budgets. Mayor Barbara Lee''s proposed amendment, developed with the Charter Reform Working Group, would make the mayor the chief executive with veto power over council decisions (subject to two-thirds override), require full-time city council positions, and expand council confirmation powers over certain department heads. The measure also establishes an Independent Budget and Legislative Analyst''s office. After initial council approval on a 5-3 vote, Mayor Lee cast a rare tie-breaking vote on June 16 to advance the measure to the November 2026 ballot, where polling shows strong public support.', '[{"development": "Mayor Barbara Lee introduced charter reform legislation following recommendations from the Mayor''s Charter Reform Working Group, co-facilitated with the League of Women Voters Oakland.", "source_url": "https://www.spur.org/news/2026-05-14/path-better-governance-oakland-takes-big-step-toward-charter-reform"}, {"development": "Oakland City Council voted 5-3 on the first reading to advance the charter reform proposal, with concerns raised by three council members about expanded mayoral powers.", "source_url": "https://www.sfchronicle.com/eastbay/article/barbara-lee-strong-mayor-november-ballot-22291395.php"}, {"development": "On June 16, the council voted 4-4 on the second reading, resulting in a tie that Mayor Lee broke by voting yes, placing the measure on the November ballot.", "source_url": "https://oaklandside.org/2026/06/16/barbara-lee-strong-mayor-oakland-november-charter"}, {"development": "Polling data showed 63% support for modernizing Oakland''s government, 63% preference for strong mayor system, and 73% support for mayoral veto power with two-thirds council override.", "source_url": "https://www.facebook.com/BarbaraLeeforCA/posts/oaklanders-are-clear-they-want-a-city-government-that-delivers-results-and-is-ac/1484267459750873"}]'::jsonb, '{"date": "2026-11-03", "body": "Oakland voters", "what": "Vote on Mayoral Powers, City Council Oversight, and Elected Officials Charter Amendment to establish strong mayor system with executive authority and veto power", "source_url": "https://ballotpedia.org/Oakland,_California,_Mayoral_Powers,_City_Council_Oversight,_and_Elected_Officials_Charter_Amendment_(November_2026)"}'::jsonb, '[{"title": "Mayor Barbara Lee''s First 100 Days of Action", "type": "City page", "date": "2025", "url": "https://blog.oaklandca.gov/the-pulse-of-the-town/100-days-of-action", "note": "Documents Charter reform taskforce assembled with League of Women Voters and planning experts, with recommendations due January 2026."}, {"title": "12-10-25-pec-special-meeting-agenda.pdf", "type": "Meeting agenda", "date": "2025-12-10", "url": "https://www.oaklandca.gov/files/assets/city/v/1/public-ethics-commission/documents/12-10-25-pec-special-meeting-agenda.pdf", "note": "Public Ethics Commission special meeting agenda addressing proposed amendments to Oakland Campaign Reform Act."}, {"title": "Oakland Makes Changes to Officeholder Account Rules", "type": "City page", "date": "2026-01-16", "url": "https://www.oaklandca.gov/Government/Boards-Commissions/Public-Ethics-Commission/Oakland-Makes-Changes-to-Officeholder-Account-Rules", "note": "Describes City Council amendments to Campaign Reform Act effective January 6, 2026, modifying contribution limits and sunset dates."}, {"title": "Police Commission | City of Oakland, CA", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/Government/Boards-Commissions/Police-Commission", "note": "Describes Police Commission role and federal oversight status related to governance accountability."}, {"title": "Boards & Commissions | City of Oakland, CA", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/Government/Boards-Commissions", "note": "Lists Oakland boards and commissions including Redistricting Commission established by Charter amendment."}, {"title": "Redistricting Commission", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/Government/Boards-Commissions/Redistricting-Commission", "note": "Describes independent Redistricting Commission established by 2014 ballot measure under Article II, Section 220 of City Charter."}, {"title": "Charter Reform Modernization | City of Oakland, CA", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/Government/City-Council-Leadership/Leadership/Office-of-the-Mayor/Charter-Reform-Modernization", "note": "Official page dedicated to Charter reform modernization initiatives."}, {"title": "Resolution No. 90827- CMS", "type": "Council resolution", "date": "2025", "url": "https://www.oaklandca.gov/files/assets/city/v/1/finance/documents/fiscal-years/2025-2027-budget/90827-c.m.s.pdf", "note": "Resolution referencing Section 801 of Oakland City Charter requiring budget adoption."}, {"title": "Children''s Initiative Oversight Commission", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/Government/Boards-Commissions/Childrens-Initiative-Oversight-Commission", "note": "Describes Children''s Initiative Commission established through Measure AA 2018 Charter Amendment."}, {"title": "DRAFT OAKLAND CITY COUNCIL", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/files/assets/city/v/1/boards-amp-commissions/documents/pec/laws-policies/other-related-policies/city-council-rules-of-procedure.pdf", "note": "Draft City Council Rules of Procedure document."}, {"title": "City of Oakland - File #: 26-0692", "type": "Council resolution", "date": "2026", "url": "https://oakland.legistar.com/LegislationDetail.aspx?ID=8005387&GUID=F62A0029-E929-44D7-9A49-6E71BA7B98AB&Options=&Search=", "note": "Proposed Ballot Measure for November 2026 election to reform Oakland City Charter including mayor powers, council confirmations, and budget analyst office."}, {"title": "Elections", "type": "City page", "date": "2026", "url": "https://www.oaklandca.gov/Government/Elections", "note": "Elections page listing November 2026 General Municipal Election with Charter reform ballot measure."}]'::jsonb, '[{"title": "Oakland council advances mayor''s charter reform proposal to 2nd vote", "outlet": "San Francisco Chronicle", "date": "2026-06-16", "url": "https://www.sfchronicle.com/eastbay/article/barbara-lee-strong-mayor-november-ballot-22291395.php"}, {"title": "Barbara Lee breaks tie to push ''strong-mayor'' measure onto ballot", "outlet": "Oaklandside", "date": "2026-06-16", "url": "https://oaklandside.org/2026/06/16/barbara-lee-strong-mayor-oakland-november-charter"}, {"title": "Oakland puts ''strong mayor'' charter reform on November ballot", "outlet": "KTVU FOX 2", "date": "2026-06-16", "url": "https://www.ktvu.com/news/oakland-puts-strong-mayor-charter-reform-on-november-ballot"}, {"title": "Oakland mayor casts tie-breaking vote to put charter reform measure on November ballot", "outlet": "Local News Matters", "date": "2026-06-18", "url": "https://localnewsmatters.org/2026/06/18/oakland-charter-reform-november-ballot"}, {"title": "Path to Better Governance: Oakland Takes a Big Step Toward Charter Reform", "outlet": "SPUR", "date": "2026-05-14", "url": "https://www.spur.org/news/2026-05-14/path-better-governance-oakland-takes-big-step-toward-charter-reform"}]'::jsonb, '[{"title": "They say Oakland government is broken — and have a plan to fix it", "author_org": "Oaklandside", "url": "https://oaklandside.org/2025/04/28/oakland-charter-reform-strong-mayor-city-manager"}, {"title": "Strong Mayoral System Recommended in Oakland Charter Reform Report", "author_org": "East Bay Rental Housing Association", "url": "https://www.ebrha.com/news/strong-mayoral-system-recommended-in-oakland-charter-reform-report"}, {"title": "Oakland charter reform: council pay raises up to 125%", "author_org": "Oakland Report", "url": "https://www.oaklandreport.org/p/city-council-pay-raises-charter-reform"}]'::jsonb, '["Specific text of all proposed charter amendments not provided in sources", "Detailed arguments from the three council members who voted against advancing the measure", "Analysis of potential fiscal impacts beyond council salary increases", "Community opposition or alternative charter reform proposals not covered", "Details on implementation timeline if measure passes in November"]'::jsonb, 24, 12, now());
