-- upte-uc-bargaining
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('UPTE-CWA / UC bargaining', 'UPTE-CWA reached a tentative agreement with UC on November 8, 2025, after 17 months of bargaining, with the contract ratified at 98% approval.', 'tracking', 'LABOR/DISPUTE', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'upte-uc-bargaining', 'UPTE-CWA / UC bargaining', 'LABOR/DISPUTE', 'UPTE-CWA reached a tentative agreement with UC on November 8, 2025, after 17 months of bargaining, with the contract ratified at 98% approval.', '2026-07-18', 'UPTE-CWA Local 9119 (University Professional and Technical Employees-Communication Workers of America) is the union representing 19,664 health care professionals, technical, and research support professional employees across the University of California system in three bargaining units: Health Care Professionals (HX), Research Support Professionals (RX), and Technical Support Professionals (TX). The union negotiates systemwide contracts covering all UC campuses, hospitals, laboratories, and related facilities. UPTE represents a diverse workforce providing critical research, technical, and healthcare support services essential to UC''s mission of excellence in education, research, and patient care.', '[{"development": "Tentative agreement reached on November 8, 2025, after 17 months of bargaining and three weeks of mediation, following UPTE''s request to resume mediation after talks broke down earlier that week.", "source_url": "https://www.universityofcalifornia.edu/press-room/joint-statement-uc-and-upte-agreement-reached-following-uptes-request-resume-mediation"}, {"development": "Contract ratified by 98% of members with nearly 12,000 votes cast, effective immediately upon ratification.", "source_url": "https://upte.org/uofcalifornia"}, {"development": "UPTE canceled its planned November 17-18 strike across UC system following the tentative agreement.", "source_url": "https://dailybruin.com/2025/11/08/after-more-than-a-year-uc-reaches-contract-with-upte-cwa-9119"}, {"development": "UC proposed wage increases up to 20% over three-year contract period but UPTE rejected the proposal, citing insufficient raises, healthcare cost increases, and inadequate work-life balance protections.", "source_url": "https://www.universityofcalifornia.edu/press-room/upte-rejects-ucs-proposal-increased-wages-medical-insurance-premium-discounts"}, {"development": "UPTE conducted one-day unfair labor practice strike on April 1, 2025, with 20,000 members participating in response to UC''s alleged unlawful unilateral healthcare cost increases and divide-and-conquer bargaining tactics.", "source_url": "https://upte.org/updates/upte-ends-1-day-unfair-labor-practice-strike-calls-on-uc-to-end-unlawful-behavior-amp-engage-in-meaningful-bargainingnbsp"}, {"development": "New contract includes title-specific equity increases, effective retroactive to first full pay period following ratification (November 23, 2025 for bi-weekly pay, December 1, 2025 for monthly pay), to be processed within 120 days.", "source_url": "https://upte.org/uofcalifornia"}, {"development": "Over 2,500 workers were brought into UPTE representation through unit modification orders in 2025, including titles such as Clinical Informatics Specialist, Broadcast Communication Specialist, Athletic Trainer, Environmental Health and Safety Specialist, and others.", "source_url": "https://upte.org/representation"}]'::jsonb, 'null'::jsonb, '[{"title": "Joint Statement from UC and UPTE: Agreement Reached Following UPTE''s Request to Resume Mediation", "type": "press_release", "date": "2025-11-08", "url": "https://www.universityofcalifornia.edu/press-room/joint-statement-uc-and-upte-agreement-reached-following-uptes-request-resume-mediation", "note": "Official announcement of tentative agreement after 17 months of bargaining and three weeks of mediation"}, {"title": "Contract for Health Care Professionals Unit (HX)", "type": "contract", "date": "2025-11-01", "url": "https://ucnet.universityofcalifornia.edu/resources/employment-policies-contracts/bargaining-units/health-care-professionals/contract", "note": "New contract ratified for period 11/1/2025 to 9/30/2028, with articles being finalized and posted"}, {"title": "UC-and-UPTE-Fact-Finding-Report.pdf", "type": "fact_finding", "date": "2025-10", "url": "https://www.universityofcalifornia.edu/sites/default/files/2025-10/UC-and-UPTE-Fact-Finding-Report.pdf", "note": "Fact-finding panel recommendations on 37 open issues including wages, benefits, and contract terms"}, {"title": "Update on UC-UPTE negotiations: May 2025", "type": "bargaining_update", "date": "2025-05-08", "url": "https://ucnet.universityofcalifornia.edu/labor-news/upte-may-2025", "note": "UC and UPTE met May 8-9, 2025 to resume bargaining with exchanges on reclassifications and healthcare costs"}, {"title": "UPTE Rejects UC''s Proposal for Increased Wages, Medical Insurance Premium Discounts", "type": "press_release", "date": "", "url": "https://www.universityofcalifornia.edu/press-room/upte-rejects-ucs-proposal-increased-wages-medical-insurance-premium-discounts", "note": "UC proposed up to 20% wage increases over three years but UPTE rejected citing insufficient compensation"}, {"title": "ACTION ITEM For Meeting of November 15, 2023", "type": "regents_meeting", "date": "2023-11-15", "url": "https://regents.universityofcalifornia.edu/regmeet/nov23/f11.pdf", "note": "UC Regents action item documenting UCRP contribution rates for UPTE-CWA Local 9119 members"}]'::jsonb, '[{"title": "After more than a year, UC reaches contract with UPTE-CWA 9119", "outlet": "Daily Bruin", "date": "2025-11-08", "url": "https://dailybruin.com/2025/11/08/after-more-than-a-year-uc-reaches-contract-with-upte-cwa-9119"}]'::jsonb, '[{"title": "TX — Technical", "author_org": "UCnet", "url": "https://ucnet.universityofcalifornia.edu/resources/employment-policies-contracts/bargaining-units/technical"}, {"title": "THE UNIVERSITY OF CALIFORNIA BARGAINING UNITS & CONTRACTS", "author_org": "UCI", "url": "https://hr.uci.edu/partnership/workforce-relations/pdf/UC-Barganing-Units+Contracts.pdf"}, {"title": "Labor News | UCnet - University of California", "author_org": "UCnet", "url": "https://ucnet.universityofcalifornia.edu/labor-news"}]'::jsonb, '["Specific language details of final ratified contract articles (noted as still being finalized as of source date)", "Complete details on all 2,500+ newly organized job titles and their wage scales", "Healthcare premium credit amounts for 2025-2028 (sources indicate premium credits exist but specific dollar amounts vary by pay band and year in different documents)", "Detailed breakdown of title-specific equity increases beyond statement that they are at least 1% retroactive to ratification", "Whether contract ratification vote occurred in November 2025 or later (source indicates ''nearly 12k votes'' but exact date unclear)", "Status of ongoing negotiations for newly organized groups of workers mentioned in UPTE ULP strike context", "Specific funding mechanisms or campus-by-campus implementation details", "Future decision points or contract reopener dates beyond the 2028 expiration"]'::jsonb, 25, 21, now());
END $$;

-- villegas-congress
DO $$
DECLARE tid uuid;
BEGIN
  INSERT INTO threads (title, description, status, archetype, search_hints, position)
  VALUES ('Randy Villegas for Congress', 'Randy Villegas (D) advanced from the June 2, 2026 primary in California''s 22nd Congressional District and is running in the November 3, 2026 general election against incumbent Republican David Valadao.', 'tracking', 'ELECTORAL/PERSON', '[]'::jsonb, 0)
  RETURNING id INTO tid;

  INSERT INTO briefings (thread_id, slug, topic, archetype, status_line, as_of, background, what_changed, next_decision_point, official_record, coverage, analysis, gaps, sources_total, primary_source_count, generated_at)
  VALUES (tid, 'villegas-congress', 'Randy Villegas for Congress', 'ELECTORAL/PERSON', 'Randy Villegas (D) advanced from the June 2, 2026 primary in California''s 22nd Congressional District and is running in the November 3, 2026 general election against incumbent Republican David Valadao.', '2026-07-16', 'Randy Villegas is a Democratic candidate running for the U.S. House to represent California''s 22nd Congressional District. The son of Mexican immigrants, Villegas is an educator, auto repair shop owner, and former school board member who has focused his career on community organizing and fighting for working-class families in the Central Valley. He advanced from the June 2, 2026 primary with 32.4% of the vote, finishing second to incumbent Republican David Valadao (40.7%), with both advancing to the November 3, 2026 general election under California''s top-two primary system. As of mid-2026, Villegas has raised over $2.6 million in his campaign, primarily from individual donors while refusing corporate PAC contributions. His campaign emphasizes healthcare reform, environmental protection, and opposition to corporate influence in politics.', '[{"development": "Speaker Emerita Pelosi, Senator Schiff, Senator Padilla, and Representatives Aguilar and Lofgren endorsed Randy Villegas", "source_url": "https://www.villegasforcongress.com"}, {"development": "Randy Villegas joined advocates to hold Valadao accountable for gutting healthcare", "source_url": "https://www.villegasforcongress.com"}, {"development": "Villegas issued statement on fatal shooting of Lorenzo Salgado Araujo", "source_url": "https://www.villegasforcongress.com"}]'::jsonb, '{"date": "2026-11-03", "body": "California voters", "what": "General election for U.S. House California District 22 between incumbent David Valadao (R) and Randy Villegas (D)", "source_url": "https://ballotpedia.org/California%27s_22nd_Congressional_District_election,_2026"}'::jsonb, '[{"title": "VILLEGAS FOR CONGRESS - Committee Overview", "type": "FEC Committee Registration", "date": "2025-04-14", "url": "https://www.fec.gov/data/committee/C00902379", "note": "Principal campaign committee, Treasurer: Lauren Decot Lee, Total receipts: $2,645,560.49"}, {"title": "June 30, 2025 Congressional Candidate Table 7", "type": "FEC Campaign Finance Report", "date": "2025-06-30", "url": "https://www.fec.gov/resources/campaign-finance-statistics/2026/tables/congressional/ConCand7_2025_6m.pdf", "note": "As of June 30, 2025: Receipts $231,316, Individual contributions $225,316, PAC contributions $6,000, Cash on hand $126,432"}, {"title": "June 2, 2026, Primary Election Notice to Candidates - Congress", "type": "California Secretary of State Election Notice", "date": "2026-06-02", "url": "https://elections.cdn.sos.ca.gov/statewide-elections/2026-primary/congress.pdf", "note": "Official candidate notice for California''s 22nd Congressional District primary"}, {"title": "Certified List of Candidates for the June 2, 2026, Primary", "type": "California Secretary of State Certified List", "date": "2026-03-26", "url": "https://elections.cdn.sos.ca.gov/statewide-elections/2026-primary/cert-list-candidates.pdf", "note": "Official certification of candidates, Villegas listed as Democratic candidate with ballot designation ''Teacher/Business Owner''"}, {"title": "June 2, 2026, Primary Election Statement of Vote", "type": "California Secretary of State Election Results", "date": "2026-06-02", "url": "https://elections.cdn.sos.ca.gov/sov/2026-primary/sov/complete-sov.pdf", "note": "Primary results: Valadao (R) 40.7% (32,491 votes), Villegas (D) 32.4% (25,808 votes), Bains (D) 26.9% (21,458 votes). Villegas advanced to general election."}, {"title": "NOTIFICATION OF MULTICANDIDATE STATUS - A New Policy PAC", "type": "FEC Form 1M", "date": "2026-02-04", "url": "https://docquery.fec.gov/pdf/008/202602049825918008/202602049825918008.pdf", "note": "A New Policy PAC made contributions to Villegas campaign as of February 4, 2026"}, {"title": "NOTIFICATION OF MULTICANDIDATE STATUS - League of Labor Voters", "type": "FEC Form 1M", "date": "2026-06-26", "url": "https://docquery.fec.gov/pdf/583/202606269874268583/202606269874268583.pdf", "note": "League of Labor Voters supported Villegas as of March 31, 2026"}]'::jsonb, '[{"title": "Interview with 2026 22nd Congressional District candidate Randy Villegas", "outlet": "KGET News", "date": "2025-04-14", "url": "https://www.youtube.com/watch?v=f6kc7wLLx90"}, {"title": "The race for District 22: A one-on-one with Randy Villegas", "outlet": "KGET 17 News", "date": "2026-06-12", "url": "https://www.kget.com/news/politics/your-local-elections/the-race-for-district-22-a-one-on-one-with-randy-villegas/amp"}, {"title": "When parties take victory laps too soon", "outlet": "Roll Call", "date": "2026-06-23", "url": "https://rollcall.com/2026/06/23/when-parties-take-victory-laps-too-soon"}, {"title": "Incumbent David Valadao (R) and Randy Villegas (D) advanced from the top-two primary for California''s 22nd Congressional District on June 2, 2026", "outlet": "Ballotpedia News", "date": "2026-06-12", "url": "https://news.ballotpedia.org/2026/06/12/incumbent-david-valadao-r-and-randy-villegas-d-advanced-from-the-top-two-primary-for-californias-22nd-congressional-district-on-june-2-2026"}]'::jsonb, '[{"title": "Randy Villegas (California) - Ballotpedia", "author_org": "Ballotpedia", "url": "https://ballotpedia.org/Randy_Villegas_(California)"}, {"title": "California''s 22nd Congressional District election, 2026 - Ballotpedia", "author_org": "Ballotpedia", "url": "https://ballotpedia.org/California%27s_22nd_Congressional_District_election,_2026"}, {"title": "Randy Villegas is the Leading Democrat in the CA-22 primary election", "author_org": "Data for Progress", "url": "https://www.filesforprogress.org/datasets/2026/5/ca22_primary_memo_2026.pdf"}, {"title": "MoveOn endorses Randy Villegas", "author_org": "MoveOn", "url": "https://front.moveon.org/endorsements/candidates/randy-villegas"}, {"title": "Courage-Endorsed Candidates, Mai Vang and Randy Villegas, Win Big in Primary Congressional Races", "author_org": "Courage California", "url": "https://couragecalifornia.org/2026-primary-election-progressive-win-mai-vang-and-randy-villegas"}, {"title": "Randy Villegas CA-22", "author_org": "Indivisible", "url": "https://indivisible.org/candidates/randy-villegas-ca-22"}, {"title": "2026 Red to Blue - DCCC", "author_org": "Democratic Congressional Campaign Committee", "url": "https://dccc.org/2026-red-to-blue"}, {"title": "2026 United States House of Representatives elections in California - Wikipedia", "author_org": "Wikipedia", "url": "https://en.wikipedia.org/wiki/2026_United_States_House_of_Representatives_elections_in_California"}]'::jsonb, '["Most recent FEC filing date beyond June 30, 2025 snapshot", "Total raised since Q2 2025 through July 2026", "Specific general election polling data", "Campaign spending breakdown by category", "Details on opposition research or negative attacks"]'::jsonb, 22, 7, now());
END $$;
